const pagos = $input.all().map(i => i.json);
let totalMonto = 0;
let totalAbonado = 0;
let totalSaldo = 0;

pagos.forEach(p => {
  totalMonto += Number(p.total_amount) || 0;
  totalAbonado += Number(p.paid_amount) || 0;
  totalSaldo += Number(p.pending_balance) || 0;
});

const ultimoPago = pagos.length > 0 ? pagos[0] : null;

return [{
  json: {
    success: true,
    totalPagos: pagos.length,
    montoTotalServicios: `$${totalMonto.toFixed(2)}`,
    montoPagado: `$${totalAbonado.toFixed(2)}`,
    saldoPendiente: `$${totalSaldo.toFixed(2)}`,
    fechaUltimoPago: ultimoPago ? ultimoPago.payment_date : 'Sin pagos registrados',
    mensajeChat: `Tu estado de cuenta refleja un total facturado de $${totalMonto.toFixed(2)}, total pagado de $${totalAbonado.toFixed(2)} y un saldo pendiente de $${totalSaldo.toFixed(2)}. Fecha de tu último movimiento: ${ultimoPago ? ultimoPago.payment_date : 'N/A'}.`,
    historialPagos: pagos
  }
}];
